<?php
namespace Database\Seeders;
use App\Models\Permission; use App\Models\Role; use Illuminate\Database\Seeder;
class RolePermissionSeeder extends Seeder { public function run():void{$items=['dashboard.view'=>'View dashboard','properties.manage'=>'Manage properties','posts.manage'=>'Manage posts','pages.manage'=>'Manage pages','categories.manage'=>'Manage categories','media.manage'=>'Manage media','menus.manage'=>'Manage menus','banners.manage'=>'Manage banners','settings.manage'=>'Manage settings','team.manage'=>'Manage team','enquiries.manage'=>'Manage enquiries','newsletters.manage'=>'Manage newsletter subscribers','widgets.manage'=>'Manage widgets','users.manage'=>'Manage users'];foreach($items as $slug=>$name)Permission::updateOrCreate(['slug'=>$slug],['name'=>$name,'group'=>strtok($slug,'.')]);$admin=Role::updateOrCreate(['slug'=>'administrator'],['name'=>'Administrator','description'=>'Full CMS access']);$admin->permissions()->sync(Permission::pluck('id')->all());$editor=Role::updateOrCreate(['slug'=>'editor'],['name'=>'Editor','description'=>'Content editing access']);$editor->permissions()->sync(Permission::whereIn('slug',['dashboard.view','posts.manage','pages.manage','categories.manage','media.manage'])->pluck('id')->all());} }